// surface-engine::lower::recursion_surface — the pre-lowering scope pass
pub(super) fn validate_item(item: SynNode<'_>) -> LowerResult<()>

// surface-engine::lower — the recursion-surface finding family (excerpt)
#[non_exhaustive]
pub enum LowerError {
    UnmarkedRecursiveReference { name: String, suggestion: String, byte_range: SourceRange },
    MarkedReferenceOutsideRecursiveScope { target: String, byte_range: SourceRange },
    ReservedNamedMeasure { resident: String, byte_range: SourceRange },
    ReservedExplicitInstantiation { resident: String, byte_range: SourceRange },
    ReservedExplicitSize { resident: String, byte_range: SourceRange },
    ReservedCostBound { resident: String, byte_range: SourceRange },
    ReservedTailAssertion { byte_range: SourceRange },
}

